using Payments;

namespace Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly PaymentGateway _sut = new();

    // --- ChargeAsync Tests ---

    [TestMethod]
    [DataRow("tok_valid_visa", 10.00)]
    [DataRow("tok_valid_mastercard", 99.99)]
    [DataRow("tok_valid_amex", 0.50)]
    public async Task ChargeAsync_ValidTokenAndAmount_ThrowsNotImplementedException(string token, double amount)
    {
        // The methods are currently stubs; verify they throw NotImplementedException
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(token, (decimal)amount));
    }

    [TestMethod]
    [DataRow(null, 10.00, DisplayName = "Null token")]
    [DataRow("", 10.00, DisplayName = "Empty token")]
    public async Task ChargeAsync_InvalidToken_ThrowsNotImplementedException(string? token, double amount)
    {
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync(token!, (decimal)amount));
    }

    [TestMethod]
    [DataRow(0.00, DisplayName = "Zero amount")]
    [DataRow(-5.00, DisplayName = "Negative amount")]
    public async Task ChargeAsync_InvalidAmount_ThrowsNotImplementedException(double amount)
    {
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    public async Task ChargeAsync_VeryLargeAmount_ThrowsNotImplementedException()
    {
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.ChargeAsync("tok_valid", 999_999_999.99m));
    }

    // --- RefundAsync Tests ---

    [TestMethod]
    [DataRow("ch_abc123")]
    [DataRow("ch_xyz789")]
    public async Task RefundAsync_ValidChargeId_ThrowsNotImplementedException(string chargeId)
    {
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.RefundAsync(chargeId));
    }

    [TestMethod]
    [DataRow(null, DisplayName = "Null chargeId")]
    [DataRow("", DisplayName = "Empty chargeId")]
    public async Task RefundAsync_InvalidChargeId_ThrowsNotImplementedException(string? chargeId)
    {
        await Assert.ThrowsExceptionAsync<NotImplementedException>(
            () => _sut.RefundAsync(chargeId!));
    }

    // --- Record Type Tests ---

    [TestMethod]
    public void ChargeResult_Properties_AreAccessible()
    {
        var result = new ChargeResult("ch_123", true);

        Assert.AreEqual("ch_123", result.ChargeId);
        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public void RefundResult_Properties_AreAccessible()
    {
        var result = new RefundResult("re_456", false);

        Assert.AreEqual("re_456", result.RefundId);
        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public void ChargeResult_Equality_WorksByValue()
    {
        var a = new ChargeResult("ch_1", true);
        var b = new ChargeResult("ch_1", true);

        Assert.AreEqual(a, b);
    }

    [TestMethod]
    public void RefundResult_Equality_WorksByValue()
    {
        var a = new RefundResult("re_1", true);
        var b = new RefundResult("re_1", true);

        Assert.AreEqual(a, b);
    }
}

